// src/agent-runtime/runtime-notification-outbox.ts
class RuntimeNotificationOutbox {
  db;
  flushing = false;
  closed = false;
  timer;
  constructor(db) {
    this.db = db;
    db.exec(`CREATE TABLE IF NOT EXISTS native_runtime_todo_context(session_id TEXT PRIMARY KEY,data TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS native_runtime_notification_outbox(id TEXT PRIMARY KEY,session_id TEXT NOT NULL,payload TEXT NOT NULL,destination TEXT NOT NULL,created_at INTEGER NOT NULL);`);
    this.timer = setInterval(() => {
      this.flush().catch(() => {
        return;
      });
    }, 3000);
    this.timer.unref();
  }
  get(sessionId) {
    const row = this.db.prepare("SELECT data FROM native_runtime_todo_context WHERE session_id=?").get(sessionId);
    return row ? JSON.parse(row.data) : undefined;
  }
  sessionForExecution(context) {
    if (!context.executionId)
      return;
    return this.db.prepare("SELECT session_id FROM native_runtime_todo_context WHERE json_extract(data,'$.serviceId')=? AND json_extract(data,'$.ownerId')=? AND json_extract(data,'$.executionId')=? LIMIT 1").get(context.serviceId, context.ownerId, context.executionId)?.session_id;
  }
  set(sessionId, context) {
    const old = this.get(sessionId);
    if (old && (old.serviceId !== context.serviceId || old.ownerId !== context.ownerId || old.executionId !== context.executionId))
      throw new Error("Native session is already bound to another Todo scope");
    this.db.prepare("INSERT INTO native_runtime_todo_context(session_id,data) VALUES(?,?) ON CONFLICT(session_id) DO UPDATE SET data=excluded.data").run(sessionId, JSON.stringify(context));
  }
  append(sessionId, runId, sequence, event, createdAt, resolveDestination) {
    if (!["ask_user", "approval_resolved", "done", "error", "turn_aborted"].includes(event.type))
      return;
    const destination = resolveDestination();
    if (!destination?.relayPath)
      return;
    this.db.prepare("INSERT OR IGNORE INTO native_runtime_notification_outbox(id,session_id,payload,destination,created_at) VALUES(?,?,?,?,?)").run(`${runId}:${sequence}`, sessionId, JSON.stringify({ runId, event, createdAt }), JSON.stringify(destination), createdAt);
  }
  async bindRun(context, runId) {
    if (context.executionId && context.relayPath) {
      await new TodoServiceClient({ serviceId: context.serviceId, descriptorPath: context.relayPath, registry: context.discoveryDirectory }).call("bind_execution", { runId });
    }
  }
  async flush() {
    if (this.flushing || this.closed)
      return;
    this.flushing = true;
    try {
      const rows3 = this.db.prepare("SELECT * FROM native_runtime_notification_outbox ORDER BY created_at,rowid LIMIT 100").all();
      const failed = new Set;
      for (const row of rows3) {
        const c = JSON.parse(row.destination);
        if (failed.has(c.serviceId))
          continue;
        try {
          await new TodoServiceClient({ serviceId: c.serviceId, descriptorPath: c.relayPath, registry: c.discoveryDirectory }).call("runtime_event", JSON.parse(row.payload));
          if (!this.closed)
            this.db.prepare("DELETE FROM native_runtime_notification_outbox WHERE id=?").run(row.id);
        } catch {
          failed.add(c.serviceId);
        }
      }
    } finally {
      this.flushing = false;
    }
  }
  close() {
    this.closed = true;
    clearInterval(this.timer);
  }
}

// src/agent-runtime/runtime-tool-injection.ts
import { createRequire as createRequire4 } from "node:module";
import { pathToFileURL as pathToFileURL3 } from "node:url";
var TODO_NATIVE_INJECTION_SUPPORT = {
  "claude-code": "session",
  qoder: "session",
  workbuddy: "launch",
  codex: "session",
  opencode: "launch",
  zcode: "session",
  "deepseek-harness": "command-bridge",
  copilot: "session"
};
function nativeTodoMcpConfiguration(context, readiness = "required") {
  const entry = createRequire4(import.meta.url).resolve("@agent/native-runtime");
  const registry2 = context.discoveryDirectory ?? process.env.AGENTROAM_DISCOVERY_DIR;
  const command = process.env.AGENT_NATIVE_NODE_BIN?.trim() || process.execPath;
  const defer = readiness === "background" ? ",deferServiceCheck:true" : "";
  return {
    command,
    args: ["--input-type=module", "-e", `import(${JSON.stringify(pathToFileURL3(entry).href)}).then(m=>m.runTodoMcpStdio({serviceId:${JSON.stringify(context.serviceId)}${defer}})).catch(e=>{console.error(e.message);process.exitCode=1})`],
    env: {
      AGENTROAM_TODO_DESCRIPTOR: context.descriptorPath,
      ...registry2 ? { AGENTROAM_DISCOVERY_DIR: registry2 } : {},
      ...command === process.execPath && process.versions.electron ? { ELECTRON_RUN_AS_NODE: "1" } : {}
    },
    ...readiness === "background" ? { readiness } : {}
  };
}
async function prepareTodoInjection(context, agentType) {
  const support = TODO_NATIVE_INJECTION_SUPPORT[agentType];
  if (!["session", "launch", "command-bridge"].includes(support))
    return { status: "unsupported", reason: support };
  if (agentType === "codex" && !context.executionId) {
    return { status: "configured", configuration: nativeTodoMcpConfiguration(context, "background") };
  }
  const client = new TodoServiceClient({ serviceId: context.serviceId, descriptorPath: context.descriptorPath, registry: context.discoveryDirectory });
  await client.call("identity");
  return { status: "configured", configuration: nativeTodoMcpConfiguration(context) };
}

